function renderManagement(){
 $('#managementCard').hidden=true;if(!simulation)return;
 const active=customers.filter(g=>!['departed','pending','exiting','bathroom'].includes(g.party.phase));
 const urgent=active.filter(g=>g.party.concern&&urgency(g.party)>=.2&&g.party.ignoredConcern!==g.party.concern.key+':'+g.party.concern.started).sort((a,b)=>urgency(b.party)-urgency(a.party));
 const visible=new Set(urgent.slice(0,state.dayNumber>=3?3:2));
 for(const g of active.filter(g=>!g.party.concern&&g.party.reliefUntil>simulation.time).slice(0,Math.max(0,2-visible.size)))visible.add(g);
 for(const g of customers){
  const p=g.party,c=p.concern,relief=!c&&p.reliefUntil>simulation.time;g.halo.visible=false;g.showComplaint=visible.has(g);
  if(!g.showComplaint){g.bubble.hidden=true;continue;}
  const critical=stage(p)==='red';let fix=null;
  if(c){const cacheKey=[c.key,state.money,simulation.layoutRevision,Math.floor(simulation.time/2)].join('/');if(!held&&g.fixCache?.key!==cacheKey)g.fixCache={key:cacheKey,value:availableFix(simulation,p,state)};fix=g.fixCache?.value;}
  const key=relief?'relief':[c.key,critical,fix?.id,fix?.price].join('/');
  if(g.bubble.dataset.need!==key){
   g.bubble.dataset.need=key;
   g.bubble.innerHTML=relief?'<div class="guest-detail relief"><b>Thank you! Much better.</b><div class="patience-track" role="progressbar" aria-label="Customer patience"><i></i></div></div>':`<div class="guest-detail ${critical?'critical':'concerned'}"><b>${complaints[c.key]||'Can you help me?'}</b><div class="patience-label">Patience <span class="patience-number"></span></div><div class="patience-track" role="progressbar" aria-label="Customer patience"><i></i></div>${fix?`<button class="guest-fix">${fix.label}${fix.price?' · $'+fix.price:''}</button>`:'<small class="no-fix">No affordable fix fits right now.</small>'}<button class="guest-dismiss">Ignore</button></div>`;
   g.bubble.querySelector('.guest-fix')?.addEventListener('click',e=>{e.stopPropagation();customerFix(g)});
   g.bubble.querySelector('.guest-dismiss')?.addEventListener('click',e=>{e.stopPropagation();p.ignoredConcern=c.key+':'+c.started;state.interventions.push({time:simulation.time,ignore:p.id,concern:p.ignoredConcern});save();renderManagement()});
  }
 }
}
function fillPatience(el,p){const fraction=p.concern?Math.max(0,p.concern.remaining/p.concern.total):1,bar=el.querySelector('.patience-track'),fill=bar?.firstElementChild;if(!fill)return;fill.style.transform=`scaleX(${fraction})`;fill.style.background=fraction>.65?'#6ba24c':fraction>.3?'#e9a52d':'#e54c3c';bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax','100');bar.setAttribute('aria-valuenow',String(Math.round(fraction*100)));const number=el.querySelector('.patience-number');if(number)number.textContent=Math.ceil(fraction*100)+'%';}

