function replayIntervention(entry){if(entry.ignore){const g=simulation.parties.find(g=>g.id===entry.ignore);if(g)g.ignoredConcern=entry.concern;return}if(entry.action)simulation.manage(entry.key,entry.action);else simulation.applyLayout(entry.cafe)}
function startDaySimulation(slot,snapshot,resume=0){cancelPlacement();selected=null;clearGuests();simulation=new CafeSimulation(snapshot,slot);simulationFinished=false;simAccumulator=0;lastSimSave=0;let replay=0;while(simulation.time+.1<=resume&&!simulation.done){while(state.interventions[replay]&&state.interventions[replay].time<=simulation.time+.001){replayIntervention(state.interventions[replay++])}simulation.tick(.1)}while(state.interventions[replay]&&state.interventions[replay].time<=resume+.1)replayIntervention(state.interventions[replay++]);for(const party of simulation.parties){const meshes=[];for(let i=0;i<party.size;i++){const mesh=makeCustomer(party.index+i);mesh.visible=false;mesh.userData.customerType=party.type;mesh.userData.showBadge=i===0;customerRoot.add(mesh);meshes.push(mesh)}const bubble=document.createElement('div');bubble.className='customer-bubble';bubble.hidden=true;$('#labels').append(bubble);const halo=new THREE.Mesh(new THREE.RingGeometry(.4,.56,32),new THREE.MeshBasicMaterial({color:0xff2929,transparent:true,opacity:.65,depthWrite:false,side:THREE.DoubleSide}));halo.rotation.x=-Math.PI/2;halo.visible=false;customerRoot.add(halo);const meters=meshes.map((mesh,i)=>{const el=document.createElement('div');el.className='customer-patience';el.hidden=true;el.innerHTML='<span>Patience</span><div class="patience-track" role="progressbar" aria-label="Customer patience"><i></i></div>';$('#labels').append(el);return el;});customers.push({party,meshes,meters,bubble,halo,seenPurchase:party.purchaseTime,trail:[],previous:{...ENTRY}})}$('#clipboardBody').hidden=true;$('#shopToggle').setAttribute('aria-expanded','false');$('#chevron').textContent='+';document.body.dataset.catalog='';document.body.dataset.panel='closed';resize();renderInspection();renderCatalog();$('#catalog').scrollTop=0;if(mode==='store')setView('wall');dayUI.live(simulation);}
