function renderGuests(now,dt,motionElapsed=dt){
 let badgeCount=0;const bubbleRects=[];
 for(const g of [...customers].sort((a,b)=>(b.party.bubbleUntil||0)-(a.party.bubbleUntil||0))){
  const p=g.party;
  if(p.served&&p.purchaseTime!==g.seenPurchase){g.seenPurchase=p.purchaseTime;animateMoney(p)}
  const trip=['toBathroom','bathroomWait','bathroom','returnSeat','needsBathroom'].includes(p.phase);
  const walking=['toOrder','toPickup','toSeat','exiting','toBathroom','returnSeat','toWait'].includes(p.phase);
  if(Math.hypot(p.pos.x-g.previous.x,p.pos.z-g.previous.z)>.12){g.trail.unshift({...p.pos});g.previous={...p.pos};g.trail=g.trail.slice(0,60)}
  for(const [i,mesh] of g.meshes.entries()){
   const d=mesh.userData,seat=p.memberSeats?.[i];
   const wantsSeat=!!seat&&(p.phase==='seated'||trip&&i>0||p.phase==='needsBathroom'||p.phase==='toSeat');
   let point=(i?g.trail[Math.min(i*4,g.trail.length-1)]:p.pos)||p.pos;
   const previous=mesh.position.clone();
   mesh.visible=!['pending','departed'].includes(p.phase)&&!(p.phase==='bathroom'&&i===0)&&(i===0||wantsSeat||g.trail.length>=i*4);
   if(!d.arrived){mesh.position.set(point.x,0,point.z);if(mesh.visible)d.arrived=true;}
   let ownRoute=false;
   if(i>0&&wantsSeat){
    if(d.seatId!==seat.id||d.routeRevision!==simulation.layoutRevision&&d.seatRoute?.length){d.seatRoute=seatingRoute(simulation,mesh.position,seat);if(d.seatRoute){d.seatId=seat.id;d.routeRevision=simulation.layoutRevision;}}
    if(d.seatRoute){point=advanceGuest(mesh.position,d.seatRoute,motionElapsed*3.1*SIMULATION_RATE*dayUI.speed);ownRoute=true;}
   }else if(i>0&&['exiting','departed'].includes(p.phase)&&seat&&d.seatId){
    if(!d.departure)d.departure=departureRoute(simulation,mesh.position,seat,ENTRY);
    if(d.departure){point=advanceGuest(mesh.position,d.departure,motionElapsed*3.1*SIMULATION_RATE*dayUI.speed);ownRoute=true;mesh.visible=d.departure.length>0;}
   }
   const seated=wantsSeat&&(i===0?p.phase==='seated'||p.phase==='needsBathroom':ownRoute&&d.seatRoute.length===0);
   if(seated)point=seat;
   const target=new THREE.Vector3(point.x,0,point.z);
   mesh.position.copy(target);
   const a=previous.clone().project(camera),b=mesh.position.clone().project(camera);
   if(Math.abs(b.x-a.x)>.00015)d.facing=b.x>a.x?1:-1;
   const moving=previous.distanceTo(mesh.position)>.001;
   mesh.rotation.y=seated?-(seat.r||0):moving?Math.atan2(-(point.x-previous.x),-(point.z-previous.z)):p.heading||0;
   d.seatHeight=seat?.y||.53;
   d.seatFacing={x:Math.sin(seat?.r||0),z:-Math.cos(seat?.r||0)};
   d.cameraDirection={x:camera.position.x-mesh.position.x,z:camera.position.z-mesh.position.z};
   d.showBadge=false;if(mesh.visible&&i===0)badgeCount++;
   d.emotion=simulation.emotionalState(p);d.urgency=urgency(p);d.warning=!!p.concern&&!['exiting','departed'].includes(p.phase);
   d.action=seated?'seated':p.phase;d.hasDrink=!!p.hasDrink;
   animatePaintedCustomer(mesh,seated?'seated':moving&&(walking||ownRoute)?'walking':'waiting',mode,now,reducedMotion);
   const meter=g.meters[i],anchor=new THREE.Vector3(mesh.position.x,seated?(seat?.y||.53)+1.25:2.05,mesh.position.z).project(camera);
   meter.hidden=!mesh.visible||['exiting','departed'].includes(p.phase)||i===0&&g.showComplaint||anchor.z>1||Math.abs(anchor.x)>1||Math.abs(anchor.y)>1;
   if(!meter.hidden){meter.style.left=((anchor.x+1)/2*viewWidth)+'px';meter.style.top=((-anchor.y+1)/2*viewHeight)+'px';fillPatience(meter,p);}

  }
  if(g.showComplaint&&!['pending','departed','exiting','bathroom'].includes(p.phase)){fillPatience(g.bubble,p);const lead=g.meshes[0].position,v=new THREE.Vector3(lead.x,2.05,lead.z).project(camera);g.bubble.hidden=v.z>1||Math.abs(v.x)>1||Math.abs(v.y)>1;let bx=clamp((v.x+1)/2*viewWidth,110,viewWidth-110),by=clamp((-v.y+1)/2*viewHeight,140,viewHeight-220);for(const rect of bubbleRects)if(Math.abs(bx-rect.x)<210&&Math.abs(by-rect.y)<170){bx=clamp(bx+(bx<rect.x?-215:215),110,viewWidth-110);if(Math.abs(bx-rect.x)<210)by=Math.max(140,rect.y-175)}bubbleRects.push({x:bx,y:by});g.bubble.style.left=bx+'px';g.bubble.style.top=by+'px';g.bubble.classList.add('problem-bubble');g.halo.position.set(lead.x,.06,lead.z);g.halo.material.opacity=reducedMotion?.65:.35+.3*(.5+.5*Math.sin(now*.004));}else{g.bubble.hidden=true;g.halo.visible=false}}}
