const pathRoot=new THREE.Group(),occupancyRoot=new THREE.Group();scene.add(pathRoot,occupancyRoot);let pathwaysVisible=false,currentForecast=null,forecastId=0,forecastTimer,forecastBase=null,lastForecastRequest=0;
