function pathStroke(a,b,color,opacity=.85){const start=new THREE.Vector3(a.x,.07,a.z),end=new THREE.Vector3(b.x,.07,b.z),len=start.distanceTo(end);if(len<.01)return;const mesh=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,len,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false}));mesh.position.copy(start).add(end).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),end.sub(start).normalize());pathRoot.add(mesh)}
function updatePathways(){clearOverlay(pathRoot);pathRoot.visible=pathwaysVisible;$('#pathLegend').hidden=!pathwaysVisible;if(!pathwaysVisible||!currentForecast)return;const colors={green:0x22cf67,yellow:0xffc128,red:0xff3149};for(const r of currentForecast.routes){if(r.blocked){const ring=new THREE.Mesh(new THREE.RingGeometry(.24,.33,24),new THREE.MeshBasicMaterial({color:colors.red,side:THREE.DoubleSide,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.set(r.target.x,.07,r.target.z);pathRoot.add(ring);continue}for(let i=1;i<r.path.length;i++){const a=r.path[i-1],b=r.path[i],delay=simulation?routeTraffic([a,b],simulation.traffic):0,color=simulation?(delay>.2?'red':delay>.06?'yellow':'green'):r.color;pathStroke(a,b,colors[color],simulation?.5:.8)}}if(simulation)for(const g of simulation.parties.filter(g=>['toOrder','toPickup','toSeat','toBathroom','exiting','returnSeat'].includes(g.phase))){const points=[g.pos,...g.path.slice(g.segment)];if(['toSeat','returnSeat','exiting'].includes(g.phase))points.pop();for(let i=1;i<points.length;i++)pathStroke(points[i-1],points[i],g.blocked>2?colors.red:g.blocked>.5?colors.yellow:colors.green,.95)}}
function updateOccupancy(){clearOverlay(occupancyRoot);if(!simulation)return;for(const table of simulation.tables){const count=simulation.seats.filter(c=>c.tableId===table.id).length;if(!count)continue;const party=simulation.booked.get(table.id);for(let i=0;i<count;i++){const dot=new THREE.Mesh(new THREE.CircleGeometry(.065,12),new THREE.MeshBasicMaterial({color:party&&i<party.size?0x49d961:0xf4edcc,depthWrite:false}));dot.rotation.x=-Math.PI/2;dot.position.set(table.x+(i-(count-1)/2)*.17,1.28,table.z);occupancyRoot.add(dot)}}}
$('#pathwaysToggle').onclick=()=>{pathwaysVisible=!pathwaysVisible;$('#pathwaysToggle').setAttribute('aria-pressed',pathwaysVisible);updatePathways()};
let previous=performance.now();function frame(now){const elapsed=Math.max(0,(now-previous)/1000),dt=Math.min(.05,elapsed);previous=now;if(!$('#dayModal').open&&!$('#resetDialog').open)moveCamera(dt);if(simulation&&!simulationFinished&&!$('#resetDialog').open){simAccumulator+=shiftAdvance(elapsed,dayUI.speed);while(simAccumulator>=.1-1e-8&&!simulation.done){simulation.tick(.1);simAccumulator-=.1}if(simulation.time-lastSimSave>5){state.runElapsed=simulation.time;save();lastSimSave=simulation.time}if(now-lastLiveUpdate>400){dayUI.live(simulation);renderManagement();updateHeat();updatePathways();updateOccupancy();if(zonesVisible)updateZones();lastLiveUpdate=now}if(simulation.done){simulationFinished=true;renderManagement();dayUI.completed(simulation.report)}}if(simulation)renderGuests(now,dt,elapsed);animatePaintedBarista(baristaCharacter,!!simulation&&(!!simulation.barista||simulation.parties.some(g=>simulation.time-g.purchaseTime<1.5)),mode,now,reducedMotion);animateEffects(now,dt);daylight();updateLabelPositions();dustCloud.visible=!state.clean;if(!reducedMotion){dustCloud.rotation.y=now*.000008;dustCloud.position.y=Math.sin(now*.0003)*.08}renderer.setScissorTest(false);renderer.clear();renderer.setViewport(0,0,viewWidth,viewHeight);renderer.setScissor(0,0,viewWidth,viewHeight);renderer.setScissorTest(true);renderer.render(scene,camera);requestAnimationFrame(frame)}
const dustPositions=[];for(let i=0;i<160;i++){dustPositions.push(Math.sin(i*71.3)*5.6,.2+((i*1.337)%3.5),Math.cos(i*57.1)*6.5)}const dustGeometry=new THREE.BufferGeometry();dustGeometry.setAttribute('position',new THREE.Float32BufferAttribute(dustPositions,3));const dustCloud=new THREE.Points(dustGeometry,new THREE.PointsMaterial({color:0xe9d5a9,size:.018,transparent:true,opacity:.42,depthWrite:false}));scene.add(dustCloud);
buildRoom();rebuildObjects();setView('wall');resize();updateBudget();$('#loading').remove();window.addEventListener('resize',resize);
function openClipboard(){selected=null;$('#clipboardBody').hidden=false;document.body.dataset.panel='open';$('#shopToggle').setAttribute('aria-expanded','true');$('#chevron').textContent='−';selectTab('furniture');resize();requestForecast()}
dayUI=createDayUI(state,{changed:()=>{save();updateBudget();renderInspection();renderCatalog();resize()},save,market:()=>{if(!held&&!$('#clipboardBody').hidden)renderCatalog()},prepare:()=>selectTab('prepare'),cancel:cancelPlacement,begin:startDaySimulation,renovate:()=>{clearGuests();selectTab('renovate');rebuildObjects();buildRoom();requestForecast();},adjust:()=>{clearGuests();openClipboard()},intervene:openClipboard,resume:()=>{selected=null;$('#clipboardBody').hidden=true;$('#shopToggle').setAttribute('aria-expanded','false');$('#chevron').textContent='+';document.body.dataset.catalog='';document.body.dataset.panel='closed';resize()},focusAlert:a=>{if(a.point){setView('wall');orbit.target.set(a.point.x,.3,a.point.z);zoom=1.3;updateCamera();pathwaysVisible=true;$('#pathwaysToggle').setAttribute('aria-pressed',true);updatePathways()}},toast});
renderCatalog();document.querySelector('[data-tab="furniture"]').setAttribute('aria-pressed','true');$('#open').onclick=()=>dayUI.requestRun();$('#storeToggle').onclick=()=>$('#shopToggle').click();dayUI.restore();if(['day-running','intervene'].includes(state.phase)){startDaySimulation('day',state.runSnapshot||cafeSnapshot(state),state.runElapsed||0);if(state.phase==='intervene')openClipboard()}requestForecast();save();requestAnimationFrame(frame);
